heo yêu cầu, áp dụng theo /giờ; hình thức hỗ trợ được thể hiện trong tên offering."},{"id":"2287573e-56ab-4d82-b125-5f48ead8d0ec","code":"TEC-SUP-SLA","description":"Gói Cam kết SLA 99.9% uptime, áp dụng theo /tháng; hình thức hỗ trợ được thể hiện trong tên offering."},{"id":"488ea8eb-b693-4c71-8480-2c0d50517941","code":"TEC-DEV-MODULE","description":"Dịch vụ Phát triển module tùy chỉnh, áp dụng theo /module; phạm vi công việc được xác nhận trước khi thực hiện."},{"id":"2dfca30e-e4d6-4839-a533-7aeae0ba1769","code":"TEC-DEV-REPORT","description":"Dịch vụ Thiết kế báo cáo dashboard, áp dụng theo /báo cáo; phạm vi công việc được xác nhận trước khi thực hiện."},{"id":"3cfb2397-4150-4283-b8d2-cf77cd466cb9","code":"TEC-DEV-MOBILE","description":"Dịch vụ Phát triển app mobile iOS Android, áp dụng theo /dự án; phạm vi công việc được xác nhận trước khi thực hiện."},{"id":"b47a53c5-40c0-46b7-add1-9d6157417edc","code":"TEC-DEV-WEBHOOK","description":"Dịch vụ Phát triển webhook automation, áp dụng theo /lần; phạm vi công việc được xác nhận trước khi thực hiện."},{"id":"f5289bff-229d-4d52-a08b-720bc1f20b0f","code":"TEC-DEV-CONSULT","description":"Dịch vụ Tư vấn giải pháp công nghệ, áp dụng theo /giờ; phạm vi công việc được xác nhận trước khi thực hiện."},{"id":"a296b799-ca80-474a-994d-7ddb83cec5d8","code":"TEC-CLD-HOSTING","description":"Dịch vụ Hosting cloud VPS 8GB RAM, áp dụng theo /tháng; cấu hình cụ thể được xác nhận trước khi cung cấp."},{"id":"8f8a42e3-fff7-491c-9047-6c771bb2c5f5","code":"TEC-CLD-BACKUP","description":"Dịch vụ Backup dữ liệu tự động hàng ngày, áp dụng theo /tháng; cấu hình cụ thể được xác nhận trước khi cung cấp."},{"id":"a4f7f298-300f-4cc6-a2af-def4acfcb5db","code":"TEC-CLD-SECURITY","description":"Dịch vụ Bảo mật quét lỗ hổng định kỳ, áp dụng theo /tháng; cấu hình cụ thể được xác nhận trước khi cung cấp."},{"id":"76834408-2a38-4b21-b212-6724fa15735b","code":"TEC-CLD-CDN","description":"Dịch vụ CDN tăng tốc website, áp dụng theo /tháng; cấu hình cụ thể được xác nhận trước khi cung cấp."}]$catalog$::jsonb;
    expected_count constant integer := 202;
    mapped_count integer;
    unique_id_count integer;
    unique_code_count integer;
    task1_count integer;
    baseline_count integer;
    total_count integer;
    updated_count integer;
BEGIN
    IF current_database() <> 'pose_crm_v2' THEN
        RAISE EXCEPTION 'Description sync aborted: connected database is %, expected pose_crm_v2.', current_database();
    END IF;

    IF current_setting('server_encoding') <> 'UTF8' THEN
        RAISE EXCEPTION 'Description sync aborted: server encoding is %, expected UTF8.', current_setting('server_encoding');
    END IF;

    IF jsonb_array_length(canonical) <> expected_count THEN
        RAISE EXCEPTION 'Canonical mapping expected % rows, actual %.', expected_count, jsonb_array_length(canonical);
    END IF;

    SELECT count(*) INTO total_count FROM offerings;
    IF total_count <> 228 THEN
        RAISE EXCEPTION 'Pre-sync offerings expected 228, actual %.', total_count;
    END IF;

    SELECT count(*) INTO task1_count
    FROM offerings
    WHERE created_at = '2026-10-02T08:00:00Z';
    IF task1_count <> expected_count THEN
        RAISE EXCEPTION 'Pre-sync Task 1 offerings expected %, actual %.', expected_count, task1_count;
    END IF;

    SELECT count(*) INTO baseline_count
    FROM offerings
    WHERE created_at <> '2026-10-02T08:00:00Z';
    IF baseline_count <> 26 THEN
        RAISE EXCEPTION 'Pre-sync V2 baseline offerings expected 26, actual %.', baseline_count;
    END IF;

    WITH canonical_rows AS (
        SELECT *
        FROM jsonb_to_recordset(canonical)
            AS c(id uuid, code varchar(80), description text)
    )
    SELECT count(*) INTO mapped_count
    FROM canonical_rows c
    JOIN offerings o ON o.id = c.id AND o.code = c.code
    WHERE o.created_at = '2026-10-02T08:00:00Z';
    IF mapped_count <> expected_count THEN
        RAISE EXCEPTION 'Task 1 UUID/code mapping mismatch: expected %, actual %.', expected_count, mapped_count;
    END IF;

    WITH canonical_rows AS (
        SELECT *
        FROM jsonb_to_recordset(canonical)
            AS c(id uuid, code varchar(80), description text)
    )
    SELECT
        count(DISTINCT c.id),
        count(DISTINCT c.code)
    INTO unique_id_count, unique_code_count
    FROM canonical_rows c;
    IF unique_id_count <> expected_count OR unique_code_count <> expected_count THEN
        RAISE EXCEPTION 'Canonical UUID/code mapping contains duplicates.';
    END IF;

    WITH canonical_rows AS (
        SELECT *
        FROM jsonb_to_recordset(canonical)
            AS c(id uuid, code varchar(80), description text)
    )
    UPDATE offerings AS o
    SET description = c.description
    FROM canonical_rows c
    WHERE o.id = c.id
      AND o.code = c.code
      AND o.created_at = '2026-10-02T08:00:00Z'
      AND o.description IS DISTINCT FROM c.description;

    GET DIAGNOSTICS updated_count = ROW_COUNT;

    WITH canonical_rows AS (
        SELECT *
        FROM jsonb_to_recordset(canonical)
            AS c(id uuid, code varchar(80), description text)
    )
    SELECT count(*) INTO mapped_count
    FROM canonical_rows c
    JOIN offerings o ON o.id = c.id
    WHERE o.code = c.code
      AND o.description = c.description
      AND o.created_at = '2026-10-02T08:00:00Z';
    IF mapped_count <> expected_count THEN
        RAISE EXCEPTION 'Post-sync description verification failed: expected %, actual %.', expected_count, mapped_count;
    END IF;

    RAISE NOTICE 'Task 1 description synchronization complete: % row(s) updated.', updated_count;
END $sync$;

COMMIT;

-- Re-running this script is safe: matching descriptions produce zero updates.
-- If any assertion raises an exception, the transaction does not commit; issue ROLLBACK
-- in the same GUI session if it remains in an aborted transaction state.
